  return {
    columns: labeled ? table.headers.slice(1) : table.headers,
    rows: table.rows.map((row) => ({
      label: cellText(row[0]),
      values: row.slice(1).map(cellText),
    })),
    ...(table.align === undefined ? {} : { align: labeled ? table.align.slice(1) : table.align }),
  }
}

